fn language(s: &str) -> Result<()> {
    if s.is_empty() {
        Err(invalid("language must be nonempty"))
    } else {
        Ok(())
    }
}

fn execute(cli: Cli) -> Result<serde_json::Value> {
    let now = chrono::Utc::now();
    if let Some(lang) = &cli.language {
        if lang.is_empty() {
            return Err(invalid("language must be nonempty"));
        }
    }
    if let Command::Init { path, timezone } = cli.command {
        return Database::init(&path, &timezone);
    }
    let path = cli.db.ok_or_else(|| invalid("--db is required"))?;
    let lang = cli.language.as_deref();
    if !matches!(cli.command, Command::Context { .. }) && lang.is_none() {
        return Err(invalid("--language is required"));
    }
    let mut db = Database::open(&path, now)?;
    match cli.command {
        Command::Context { limit } => db.context(lang, limit),
        Command::Get { ids } => db.get(lang.unwrap(), &ids),
        Command::List {
            due,
            retired,
            since,
            search,
            limit,
            cursor,
        } => db.list(
            lang.unwrap(),
            Filters {
                due,
                retired,
                since,
                search,
            },
            limit,
            cursor.as_deref(),
        ),
        Command::Replace { file } => {
            let mut input = String::new();
            if file.as_os_str() == "-" {
                std::io::stdin()
                    .read_to_string(&mut input)
                    .map_err(|e| invalid(e.to_string()))?;
            } else {
                input = std::fs::read_to_string(file).map_err(|e| {
                    if e.kind() == std::io::ErrorKind::InvalidData {
                        invalid(e.to_string())
                    } else {
                        e.into()
                    }
                })?;
            }
            let request = serde_json::from_str(&input).map_err(|e| invalid(e.to_string()))?;
            db.replace(lang.unwrap(), request)
        }
        Command::Schedule {
            ids,
            in_days,
            on,
            clear,
        } => db.schedule(
            lang.unwrap(),
            &ids,
            if clear {
                None
            } else {
                Some(Review { in_days, on })
            },
        ),
        Command::Init { .. } => unreachable!(),
    }
}

pub fn list(
    &self,
    lang: &str,
    filters: Filters,
    limit: usize,
    cursor: Option<&str>,
) -> Result<Value> {
    language(lang)?;
    check_limit(limit)?;
    if filters.due && filters.retired {
        return Err(invalid("due and retired are incompatible"));
    }
    let since = filters.since.as_deref().map(date).transpose()?;
    let (cutoff, offset) = if let Some(token) = cursor {
        let c: Cursor = serde_json::from_str(token).map_err(|_| invalid("malformed cursor"))?;
        if c.database != self.identity || c.language != lang || c.filters != filters {
            return Err(invalid("cursor database, language, or filters differ"));
        }
        (date(&c.cutoff)?, c.offset)
    } else {
        (self.today(), 0)
    };
    let mut records = self.all(lang)?;
    records.retain(|r| {
        let active = r.retired_at.is_none();
        if active == filters.retired {
            return false;
        }
        if filters.due
            && !r
                .review_on
                .as_ref()
                .is_some_and(|d| d <= &cutoff.to_string())
        {
            return false;
        }
        if let Some(since) = since {
            let Ok(instant) = DateTime::parse_from_rfc3339(&r.created_at) else {
                return false;
            };
            if instant.with_timezone(&self.timezone).date_naive() < since {
                return false;
            }
        }
        if let Some(search) = &filters.search {
            if !r.content.to_string().contains(search) {
                return false;
            }
        }
        true
    });
    if filters.due {
        records.sort_by(|a, b| {
            a.review_on
                .cmp(&b.review_on)
                .then(a.created_at.cmp(&b.created_at))
                .then(a.id.cmp(&b.id))
        });
    } else {
        records.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.id.cmp(&b.id)));
    }
    if offset > records.len() {
        return Err(invalid("cursor offset out of bounds"));
    }
    let end = offset.saturating_add(limit).min(records.len());
    let next = if end < records.len() {
        Some(
            serde_json::to_string(&Cursor {
                database: self.identity.clone(),
                language: lang.into(),
                filters,
                cutoff: cutoff.to_string(),
                offset: end,
            })
            .unwrap(),
        )
    } else {
        None
    };
    Ok(json!({"records": &records[offset..end],"next_cursor":next}))
}

pub fn context(&self, lang: Option<&str>, limit: usize) -> Result<Value> {
    check_limit(limit)?;
    if let Some(lang) = lang {
        language(lang)?;
    }
    let mut stmt = self
        .conn
        .prepare("SELECT DISTINCT language FROM records ORDER BY language")?;
    let languages = stmt
        .query_map([], |r| r.get::<_, String>(0))?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let mut result = json!({"now":self.now.to_rfc3339_opts(chrono::SecondsFormat::Nanos,true),"today":self.today().to_string(),"timezone":self.timezone.to_string(),"languages":languages});
    if let Some(lang) = lang {
        let mut pinned = self
            .all(lang)?
            .into_iter()
            .filter(|r| r.pinned && r.retired_at.is_none())
            .collect::<Vec<_>>();
        pinned.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.id.cmp(&b.id)));
        result["language"] = json!(lang);
        result["pinned"] = json!(pinned);
        result["due"] = self.list(
            lang,
            Filters {
                due: true,
                ..Default::default()
            },
            limit,
            None,
        )?;
        result["recent"] = self.list(lang, Filters::default(), limit, None)?;
    }
    Ok(result)
}

fn json_roundtrip_scope_and_collision() {
    let (_dir, mut db) = setup("UTC");
    assert!(db.context(Some(""), 20).is_err());
    assert!(db.list("", Filters::default(), 20, None).is_err());
    assert_eq!(
        db.list("empty", Filters::default(), 20, None).unwrap()["records"],
        json!([])
    );
    let values = vec![
        Value::Null,
        json!(true),
        json!(42),
        json!(2.5),
        json!("πήγα"),
        json!([1, null]),
        json!({"kind":"practice","related_to":["nonexistent"],"z":{"b":2,"a":1}}),
    ];
    for v in values {
        let id = add(&mut db, "el", v.clone());
        assert!(
            id.len() >= 6
                && id
                    .bytes()
                    .all(|x| x.is_ascii_hexdigit() && !x.is_ascii_uppercase())
        );
        let r = record(&db, "el", &id);
        assert_eq!(r["content"], v);
        assert_eq!(r["pinned"], false);
        assert!(r["review_on"].is_null());
        assert_eq!(r["created_at"], "2026-10-17T12:00:00.000000000Z");
        assert_eq!(r.as_object().unwrap().len(), 8);
        assert_eq!(
            db.get("EL", std::slice::from_ref(&id)).unwrap_err().code,
            "record_missing"
        );
    }
    let mut ids = ["abcdef", "abcdef", "123456"].into_iter();
    let a = db
        .replace_with_ids(
            "EL",
            request(json!({"ids":[],"replacements":[{"content":null},{"content":false}]})),
            || ids.next().unwrap().into(),
        )
        .unwrap();
    assert_eq!(a["created"], json!(["abcdef", "123456"]));
    db.replace("EL", request(json!({"ids":["abcdef"],"replacements":[]})))
        .unwrap();
    let mut ids = ["abcdef", "fedcba"].into_iter();
    assert_eq!(
        db.replace_with_ids(
            "EL",
            request(json!({"ids":[],"replacements":[{"content":null}]})),
            || ids.next().unwrap().into()
        )
        .unwrap()["created"],
        json!(["fedcba"])
    );
    assert_eq!(
        db.context(None, 20).unwrap()["languages"],
        json!(["EL", "el"])
    );
}

fn scope_context_empty_and_events_preserve_handoff() {
    let (dir, mut db) = setup("UTC");
    let foreign=db.replace("fr",request(json!({"ids":[],"replacements":[{"content":"secret","pinned":true,"review":{"in_days":0}}]}))).unwrap()["created"][0].as_str().unwrap().to_owned();
    let empty = db.context(Some("el"), 20).unwrap();
    for section in ["recent", "due"] {
        assert_eq!(empty[section]["records"], json!([]));
        assert!(empty[section]["next_cursor"].is_null());
    }
    assert_eq!(empty["pinned"], json!([]));
    assert_eq!(
        db.list("el", Filters::default(), 20, None).unwrap()["records"],
        json!([])
    );
    let own = add(&mut db, "el", json!("local"));
    let before = record(&db, "fr", &foreign);
    assert_eq!(
        db.replace(
            "el",
            request(json!({"ids":[own,foreign],"replacements":[{"content":null}]}))
        )
        .unwrap_err()
        .code,
        "record_missing"
    );
    assert_eq!(record(&db, "fr", &foreign), before);
    assert_eq!(record(&db, "el", &own)["retired_at"], Value::Null);
    db.replace("fr", request(json!({"ids":[foreign],"replacements":[]})))
        .unwrap();
    let c = rusqlite::Connection::open(dir.path().join("db")).unwrap();
    let (timestamp, retired): (String, String) = c
        .query_row(
            "SELECT timestamp,retired FROM events ORDER BY rowid DESC LIMIT 1",
            [],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .unwrap();
    assert_eq!(timestamp, "2026-10-17T12:00:00.000000000Z");
    assert_eq!(
        serde_json::from_str::<Value>(&retired).unwrap(),
        json!([{"id":foreign,"previous_pinned":true,"previous_review_on":"2026-10-17"}])
    );
    assert_eq!(
        db.context(None, 20).unwrap()["languages"],
        json!(["el", "fr"])
    );
}

fn subprocess_contract() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("db");
    let p = path.to_str().unwrap();
    let version = run(&["--version"], None);
    assert!(version.status.success());
    assert!(version.stderr.is_empty());
    assert_eq!(
        String::from_utf8(version.stdout).unwrap(),
        format!("language-lab {}\n", env!("CARGO_PKG_VERSION"))
    );
    for sub in [
        None,
        Some("init"),
        Some("context"),
        Some("get"),
        Some("list"),
        Some("replace"),
        Some("schedule"),
    ] {
        let mut args = vec![];
        if let Some(sub) = sub {
            args.push(sub);
        }
        args.push("--help");
        let out = run(&args, None);
        assert!(out.status.success());
        assert!(out.stderr.is_empty());
        let text = String::from_utf8(out.stdout).unwrap();
        assert!(text.contains("Usage:"));
        if sub.is_none() {
            for name in ["init", "context", "get", "list", "replace", "schedule"] {
                assert!(text.contains(name));
            }
        }
    }
    failure(run(&["--db", p, "context"], None), "database_missing");
    assert!(!path.exists());
    assert_eq!(
        success(run(&["init", p, "--timezone", "Europe/Berlin"], None)),
        json!({"database":p,"timezone":"Europe/Berlin"})
    );
    let baseline = std::fs::read(&path).unwrap();
    for args in [
        vec!["context"],
        vec!["--db", p, "list"],
        vec!["--db", p, "--language", "", "context"],
        vec!["--db", p, "--language", "el", "get"],
        vec!["--db", p, "--language", "el", "schedule", "--clear"],
        vec!["--db", p, "--language", "el", "schedule", "abcdef"],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--clear",
            "--in-days",
            "1",
        ],
        vec!["--db", p, "context", "extra"],
        vec!["--db", p, "context", "--unknown"],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--in-days",
            "-1",
        ],
        vec![
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            "abcdef",
            "--in-days",
            "1.5",
        ],
        vec!["--db", p, "--language", "el", "list", "--due", "--retired"],
        vec!["--db", p, "--language", "el", "replace"],
    ] {
        failure(run(&args, None), "invalid_input");
        assert_eq!(std::fs::read(&path).unwrap(), baseline);
    }
    failure(
        run(&["init", p, "--timezone", "UTC"], None),
        "storage_error",
    );
    assert_eq!(std::fs::read(&path).unwrap(), baseline);
    let args = ["--db", p, "--language", "el", "replace", "--file", "-"];
    for input in [
        b"{}".as_slice(),
        b"{} {}",
        b"\xff",
        br#"{"ids":[],"replacements":[{}]}"#,
    ] {
        failure(run(&args, Some(input)), "invalid_input");
    }
    let created = success(run(
        &args,
        Some(br#"{"ids":[],"replacements":[{"content":null}]}"#),
    ));
    let id = created["created"][0].as_str().unwrap();
    let request = dir.path().join("request.json");
    std::fs::write(
        &request,
        r#"{"ids":[],"replacements":[{"content":{"custom":true}}]}"#,
    )
    .unwrap();
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "replace",
            "--file",
            request.to_str().unwrap(),
        ],
        None,
    ));
    assert_eq!(
        success(run(&["--db", p, "--language", "el", "get", id, id], None))["records"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            id,
            "--in-days",
            "0",
        ],
        None,
    ));
    success(run(
        &[
            "--db",
            p,
            "--language",
            "el",
            "schedule",
            id,
            "--on",
            "2026-01-01",
        ],
        None,
    ));
    success(run(
        &["--db", p, "--language", "el", "schedule", id, "--clear"],
        None,
    ));
    assert_eq!(
        success(run(&["--db", p, "--language", "el", "list"], None))["records"]
            .as_array()
            .unwrap()
            .len(),
        2
    );
    success(run(&["--db", p, "context"], None));
    success(run(&["--db", p, "--language", "el", "context"], None));
    failure(
        run(&["--db", p, "--language", "fr", "get", id], None),
        "record_missing",
    );
}

use chrono::{DateTime, Utc};
use language_lab::{Database, Filters, Replacement, Review};
use serde_json::{json, Value};
use tempfile::TempDir;
fn instant(s: &str) -> DateTime<Utc> {
    s.parse().unwrap()
}
const NOW: &str = "2026-10-17T12:00:00Z";
fn setup(zone: &str) -> (TempDir, Database) {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("db");
    Database::init(&p, zone).unwrap();
    let db = Database::open(&p, instant(NOW)).unwrap();
    (dir, db)
}
fn request(v: Value) -> Replacement {
    serde_json::from_value(v).unwrap()
}
fn add(db: &mut Database, lang: &str, content: Value) -> String {
    db.replace(
        lang,
        request(json!({"ids":[],"replacements":[{"content":content}]})),
    )
    .unwrap()["created"][0]
        .as_str()
        .unwrap()
        .into()
}
fn record(db: &Database, lang: &str, id: &str) -> Value {
    db.get(lang, &[id.into()]).unwrap()["records"][0].clone()
}
fn review(days: u64) -> Option<Review> {
    Some(Review {
        in_days: Some(days),
        on: None,
    })
}

use serde_json::{json, Value};
use std::{
    io::Write,
    process::{Command, Output, Stdio},
};
fn run(args: &[&str], input: Option<&[u8]>) -> Output {
    let mut c = Command::new(env!("CARGO_BIN_EXE_language-lab"));
    c.args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = c.spawn().unwrap();
    if let Some(input) = input {
        child.stdin.take().unwrap().write_all(input).unwrap();
    }
    child.wait_with_output().unwrap()
}
fn success(out: Output) -> Value {
    assert!(
        out.status.success(),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(out.stderr.is_empty());
    serde_json::from_slice(&out.stdout).unwrap()
}
fn failure(out: Output, code: &str) {
    assert!(!out.status.success());
    assert!(out.stdout.is_empty());
    let v: Value = serde_json::from_slice(&out.stderr).unwrap();
    assert_eq!(v["error"]["code"], code);
    assert!(v["error"]["message"].is_string());
}
